import React from "react";

const AchievementSection = ({ achievements }) => {
  return (
    <div>
      <h2 className="text-3xl font-bold mb-8">Prestasi</h2>
      <div className="flex flex-col space-y-6">
        {achievements.map((achievement) => (
          <div
            key={achievement.id}
            className="bg-gray-800 p-6 rounded-lg shadow-lg border-l-4 border-blue-500 transform transition-all duration-300 hover:-translate-y-2"
          >
            <div className="flex items-center mb-2">
              {/* Ikon Medali */}
              <svg
                className="w-6 h-6 text-yellow-400 mr-2"
                fill="currentColor"
                viewBox="0 0 20 20"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  fillRule="evenodd"
                  d="M10 18a8 8 0 100-16 8 8 0 000 16zm-1-5l1.5-1.5L9 10l1.5-1.5L9 7l1-1 1.5 1.5L13 6l1 1-1.5 1.5L13 10l-1.5 1.5L13 13l-1 1-1.5-1.5L9 13z"
                  clipRule="evenodd"
                />
              </svg>

              <h3 className="text-lg font-bold text-white">
                {achievement.title}
              </h3>
            </div>
            <div className="flex items-center text-sm text-gray-400 mb-3">
              <span>{achievement.organization}</span>
              <span className="mx-2">•</span>
              <span>{achievement.year}</span>
            </div>
            <p className="text-gray-300">{achievement.description}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AchievementSection;
